import Foundation
import GRDB
import OriveoProviderKit
import Testing
@testable import Oriveo

// The Memory page's "Memory suggestions" entry row and the inbox page's list / save / edit / dismiss (excluding the switch).
// Assertions come from the production path: candidates are generated by MemoryCandidateRepository.generate, and MemoryInboxModel reads and writes the real repository.

/// Every request gets 503: only the user message needs to land, no real reply is needed.
private final class MemoryInboxStubProtocol: URLProtocol, @unchecked Sendable {
    static func session() -> URLSession {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [MemoryInboxStubProtocol.self]
        return URLSession(configuration: configuration)
    }

    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
        let response = HTTPURLResponse(url: request.url!, statusCode: 503, httpVersion: nil, headerFields: nil)!
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: Data())
        client?.urlProtocolDidFinishLoading(self)
    }

    override func stopLoading() {}
}

@Suite("MemoryInboxPresentation", .serialized, .sharedProcessState)
struct MemoryInboxPresentationTests {
    /// Explicit "remember ..." -> candidate.
    private static let remember = "zh_explicit_01_golden"
    /// Global directive -> candidate.
    private static let globalDirective = "zh_implicit_04_golden"

    private struct IntentFixture: Decodable {
        struct Case: Decodable {
            let id: String
            let text: String
        }

        let cases: [Case]
    }

    /// The text of a fixture case; walks up from #filePath to find the repository root.
    private static func text(_ caseID: String) throws -> String {
        var folder = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        while folder.path != "/" {
            let url = folder.appendingPathComponent("shared/context-contracts/memory-intent.v1.json")
            if FileManager.default.fileExists(atPath: url.path) {
                let fixture = try JSONDecoder().decode(IntentFixture.self, from: Data(contentsOf: url))
                return try #require(fixture.cases.first { $0.id == caseID }?.text, "missing case \(caseID)")
            }
            folder.deleteLastPathComponent()
        }
        throw CocoaError(.fileNoSuchFile)
    }

    private static func nowMs() -> Int64 {
        Int64(Date().timeIntervalSince1970 * 1000)
    }

    @MainActor
    private func withState(_ body: (AppState) async throws -> Void) async rethrows {
        let uid = "memory-inbox-\(UUID().uuidString)"
        let state = AppState(seedDemoData: false, sessionUID: uid)
        defer {
            DatabaseManager.shared.close()
            try? FileManager.default.removeItem(at: AppSessionStore.userDir(for: uid))
        }
        try await body(state)
    }

    /// An AppState with a sendable conversation (sending goes through the real entry point, and every request gets 503).
    @MainActor
    private func withConversation(_ body: (AppState, Conversation) async throws -> Void) async rethrows {
        let uid = "memory-inbox-\(UUID().uuidString)"
        let suiteName = "memory-inbox-\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suiteName)!
        let state = AppState(seedDemoData: false, sessionUID: uid, providerSession: MemoryInboxStubProtocol.session())
        state.directiveSuggestions = DirectiveSuggestionController(defaults: defaults)
        let provider = TestFactories.makeProvider()
        state.providers = [provider]
        let conversation = TestFactories.makeConversation(
            hasCustomTitle: true,
            providerID: provider.id,
            modelID: "gpt-4o",
            messages: [TestFactories.makeMessage()]
        )
        state.upsertConversationProjection(conversation)
        defer {
            state.flushConversationPersistQueue()
            DatabaseManager.shared.close()
            try? FileManager.default.removeItem(at: AppSessionStore.userDir(for: uid))
            defaults.removePersistentDomain(forName: suiteName)
        }
        // Wait for the send tasks before the partition is deleted: failure wrap-up still writes (cost refresh) after the session is removed.
        do {
            try await body(state, conversation)
        } catch {
            await state.chatManager.waitForSendTasksForTesting()
            throw error
        }
        await state.chatManager.waitForSendTasksForTesting()
    }

    /// Sends one sentence and waits for background candidate generation to finish.
    @MainActor
    private func send(_ text: String, _ state: AppState, _ conversationID: UUID) async {
        _ = await state.sendMessage(text, in: conversationID)
        await state.memoryCandidateGeneration?.value
    }

    /// Creates a candidate through the repository generation entry point; ageMs makes the order distinguishable.
    @MainActor
    private func generate(_ caseID: String, ageMs: Int64, _ state: AppState) async throws -> MemoryCandidate {
        let repository = try #require(state.memoryCandidateRepository())
        let candidate = try await repository.generate(
            text: try Self.text(caseID),
            messageId: UUID().uuidString,
            conversationId: UUID().uuidString,
            folderId: nil,
            useMemory: true,
            nowMs: Self.nowMs() - ageMs
        )
        return try #require(candidate)
    }

    @MainActor
    private func pendingIDs(_ state: AppState) async throws -> [String] {
        let repository = try #require(state.memoryCandidateRepository())
        return try await repository.pending(nowMs: Self.nowMs()).map(\.id)
    }

    @Test("inbox_lists_pending_newest_first")
    @MainActor
    func inboxListsPendingNewestFirst() async throws {
        try await withState { state in
            let older = try await generate(Self.remember, ageMs: 2_000, state)
            let newer = try await generate(Self.globalDirective, ageMs: 1_000, state)

            let model = MemoryInboxModel()
            await model.reload(appState: state)
            #expect(model.candidates.map(\.id) == [newer.id, older.id])
            #expect(model.candidates.map(\.id) == (try await pendingIDs(state)))
            #expect(model.candidates.first?.content == newer.content)
            #expect(model.showsEmptyState == false)
            #expect(MemoryInboxModel.group(for: newer) == (MemoryItemGroup(kind: newer.proposedKind) ?? .about))
        }
    }

    @Test("entry_row_shows_pending_count")
    @MainActor
    func entryRowShowsPendingCount() async throws {
        try await withState { state in
            let model = MemoryInboxModel()
            await model.reload(appState: state)
            #expect(model.entryValue == nil)
            #expect(MemoryInboxModel.entryValue(pendingCount: 0) == nil)

            _ = try await generate(Self.remember, ageMs: 2_000, state)
            _ = try await generate(Self.globalDirective, ageMs: 1_000, state)
            await model.reload(appState: state)
            #expect(model.entryValue == "2")
        }
    }

    @Test("inbox_save_creates_item_and_undo_deletes_it")
    @MainActor
    func inboxSaveCreatesItemAndUndoDeletesIt() async throws {
        try await withState { state in
            let candidate = try await generate(Self.remember, ageMs: 1_000, state)
            let model = MemoryInboxModel()
            await model.reload(appState: state)

            // Go through the entry point the UI actually calls: save -> the row disappears + a "saved to memory" toast with 5 s undo.
            await model.saveWithUndoToast(candidate, appState: state).value
            #expect(model.candidates.isEmpty)
            let items = try #require(state.memoryItemRepository())
            let item = try #require(items.list().first)
            #expect(items.list().count == 1)
            #expect(item.content == candidate.content)
            #expect(item.kind == candidate.proposedKind)
            #expect(item.status == .active)
            #expect(try await pendingIDs(state).isEmpty)

            let toast = try #require(ToastManager.shared.current)
            #expect(toast.message == L10n.tr("memory_suggestion_saved", table: .chat))
            #expect(toast.actionTitle == L10n.tr("Undo", table: .notes))
            #expect(ToastManager.shared.currentDuration == 5)

            // Undo = the item repository deletes the just-created item normally.
            ToastManager.shared.performCurrentAction()
            // The tombstone is written in the background: wait for it to land before asserting.
            await state.waitForMemoryItemUndo()
            #expect(items.list().isEmpty)
            #expect(items.allItems().first { $0.id == item.id }?.status == .deleted)
        }
    }

    @Test("inbox_edit_saves_edited_content")
    @MainActor
    func inboxEditSavesEditedContent() async throws {
        try await withState { state in
            let candidate = try await generate(Self.globalDirective, ageMs: 1_000, state)
            let model = MemoryInboxModel()
            await model.reload(appState: state)

            // New state prefills the body, grouped by proposedKind (unmappable kinds preselect "About me").
            let target = model.edit(candidate)
            var editor = target.state
            #expect(editor.isNew)
            #expect(editor.text == candidate.content)
            #expect(editor.category == (MemoryItemGroup(kind: candidate.proposedKind) ?? .about))

            // Group unchanged: kind follows the candidate.
            editor.text = "  edited memory text  "
            await model.saveEditedWithUndoToast(editor, for: target, appState: state).value
            #expect(model.candidates.isEmpty)
            let items = try #require(state.memoryItemRepository())
            let item = try #require(items.list().first)
            #expect(items.list().count == 1)
            #expect(item.content == "edited memory text")
            #expect(item.kind == candidate.proposedKind)
            #expect(try await pendingIDs(state).isEmpty)
            #expect(ToastManager.shared.current?.message == L10n.tr("memory_suggestion_saved", table: .chat))

            // Group changed: kind is the representative kind of the new group.
            let second = try await generate(Self.remember, ageMs: 500, state)
            await model.reload(appState: state)
            let secondTarget = model.edit(second)
            var regrouped = secondTarget.state
            regrouped.category = regrouped.category == .projects ? .preferences : .projects
            let expectedKind = regrouped.category.kind(keeping: nil)
            let saved = try #require(await model.saveEdited(regrouped, for: secondTarget, appState: state))
            #expect(saved.kind == expectedKind)
            #expect(saved.content == second.content)
        }
    }

    @Test("inbox_ignore_rejects_candidate")
    @MainActor
    func inboxIgnoreRejectsCandidate() async throws {
        try await withState { state in
            let candidate = try await generate(Self.remember, ageMs: 1_000, state)
            let model = MemoryInboxModel()
            await model.reload(appState: state)

            await model.ignoreTask(candidate, appState: state).value
            #expect(model.candidates.isEmpty)
            #expect(try await pendingIDs(state).isEmpty)
            #expect(try #require(state.memoryItemRepository()).list().isEmpty)

            // A rejection leaves a fingerprint: the same sentence does not generate a candidate again.
            let repository = try #require(state.memoryCandidateRepository())
            let again = try await repository.generate(
                text: try Self.text(Self.remember),
                messageId: UUID().uuidString,
                conversationId: UUID().uuidString,
                folderId: nil,
                useMemory: true,
                nowMs: Self.nowMs()
            )
            #expect(again == nil)
            await model.reload(appState: state)
            #expect(model.candidates.isEmpty)
        }
    }

    @Test("inbox_empty_shows_empty_state")
    @MainActor
    func inboxEmptyShowsEmptyState() async throws {
        try await withState { state in
            let model = MemoryInboxModel()
            // No empty state is drawn before the first read comes back.
            #expect(model.showsEmptyState == false)
            await model.reload(appState: state)
            #expect(model.candidates.isEmpty)
            #expect(model.showsEmptyState)
            #expect(model.entryValue == nil)
        }
    }

    @Test("no_candidate_becomes_active_without_accept")
    @MainActor
    func noCandidateBecomesActiveWithoutAccept() async throws {
        try await withState { state in
            let first = try await generate(Self.remember, ageMs: 2_000, state)
            _ = try await generate(Self.globalDirective, ageMs: 1_000, state)
            let model = MemoryInboxModel()
            await model.reload(appState: state)
            await model.reload(appState: state)
            _ = model.edit(first)
            await model.ignore(first, appState: state)

            // Listing, opening the editor and dismissing do not create items; only accept enters the items table.
            let items = try #require(state.memoryItemRepository())
            #expect(items.allItems().isEmpty)
            #expect(model.candidates.count == 1)
            #expect(try await pendingIDs(state).count == 1)
        }
    }

    @Test("auto_suggest_defaults_on_and_persists")
    @MainActor
    func autoSuggestDefaultsOnAndPersists() async throws {
        try await withState { state in
            let model = MemoryInboxModel()
            await model.reload(appState: state)
            #expect(model.autoSuggestEnabled)

            _ = try await generate(Self.remember, ageMs: 1_000, state)
            model.setAutoSuggestEnabled(false, appState: state)
            #expect(model.autoSuggestEnabled == false)
            #expect(try #require(state.memoryCandidateRepository()).autoSuggestEnabled() == false)

            // A new model instance is still off; turning it off does not delete existing pending candidates, and the list stays as is.
            let reopened = MemoryInboxModel()
            await reopened.reload(appState: state)
            #expect(reopened.autoSuggestEnabled == false)
            #expect(reopened.candidates.count == 1)

            reopened.setAutoSuggestEnabled(true, appState: state)
            let again = MemoryInboxModel()
            await again.reload(appState: state)
            #expect(again.autoSuggestEnabled)
        }
    }

    @Test("auto_suggest_off_skips_implicit_keeps_explicit")
    @MainActor
    func autoSuggestOffSkipsImplicitKeepsExplicit() async throws {
        try await withConversation { state, conversation in
            let model = MemoryInboxModel()
            await model.reload(appState: state)
            model.setAutoSuggestEnabled(false, appState: state)

            // Implicit global directive: no candidate, no memory item.
            await send(try Self.text(Self.globalDirective), state, conversation.id)
            #expect(try await pendingIDs(state).isEmpty)
            #expect(state.memorySuggestions.pending(in: conversation.id) == nil)

            // An explicit "remember" still produces a candidate.
            await send("\u{8BB0}\u{4F4F}\u{6211}\u{504F}\u{597D}\u{7B80}\u{6D01}\u{56DE}\u{7B54}", state, conversation.id)
            let candidates = try await pendingIDs(state)
            #expect(candidates.count == 1)
            let suggestion = try #require(state.memorySuggestions.pending(in: conversation.id)?.candidate)
            #expect(suggestion.id == candidates.first)
            await model.reload(appState: state)
            #expect(model.candidates.map(\.id) == candidates)
        }
    }

    @Test("inbox_undo_survives_leaving_page")
    @MainActor
    func inboxUndoSurvivesLeavingPage() async throws {
        try await withState { state in
            let candidate = try await generate(Self.remember, ageMs: 1_000, state)
            var model: MemoryInboxModel? = MemoryInboxModel()
            await model?.reload(appState: state)
            await model?.saveWithUndoToast(candidate, appState: state).value
            let items = try #require(state.memoryItemRepository())
            let item = try #require(items.list().first)

            // Leaving the inbox page: after the model is released, tapping undo within 5 s still deletes the just-created item.
            weak let released = model
            model = nil
            #expect(released == nil)
            ToastManager.shared.performCurrentAction()
            // The tombstone is written in the background: wait for it to land before asserting.
            await state.waitForMemoryItemUndo()
            #expect(items.list().isEmpty)
            #expect(items.allItems().first { $0.id == item.id }?.status == .deleted)
        }
    }

    @Test("inbox_load_failure_keeps_previous_list")
    @MainActor
    func inboxLoadFailureKeepsPreviousList() async throws {
        try await withState { state in
            let older = try await generate(Self.remember, ageMs: 2_000, state)
            let newer = try await generate(Self.globalDirective, ageMs: 1_000, state)
            let model = MemoryInboxModel()
            await model.reload(appState: state)
            #expect(model.candidates.map(\.id) == [newer.id, older.id])

            // The candidate table cannot be read: pending() throws.
            let pool = try DatabaseManager.shared.openIfNeeded(for: state.sessionPartitionUID)
            try await pool.write { db in
                try db.execute(sql: "ALTER TABLE \(MemoryCandidateStore.table) RENAME TO memory_inbox_test_broken")
            }

            // An existing list: keep the previous one.
            await model.reload(appState: state)
            #expect(model.candidates.map(\.id) == [newer.id, older.id])
            #expect(model.showsEmptyState == false)

            // Failing on the first load: treat as the empty state.
            let fresh = MemoryInboxModel()
            await fresh.reload(appState: state)
            #expect(fresh.candidates.isEmpty)
            #expect(fresh.showsEmptyState)
        }
    }
}
